#!/bin/bash
set -e

# Fix: visit_number was never included in the invoice's Supabase select,
# so VISIT ID showed blank even though the template had the placeholder.
# Also: moved VISIT ID to directly below PATIENT ID (was under Visit Date
# on the right), and Surgery Bill's operated eye now shows 'Right (OD)' /
# 'Left (OS)' matching the same convention used in OT Intraop.
# Run this from your veda-hmis repo root in Codespaces.

mkdir -p "app/print-templates"
echo "" | base64 -d > "app/print-templates/actions.js"
echo "Wrote app/print-templates/actions.js"

git add app/print-templates/actions.js
git commit -m "Fix Visit ID missing from bills; reposition under Patient ID; eye label Right/Left(OD/OS)"
git push

echo "Done."
